import { useEffect, useState } from "react";
import API from "../services/adminApi";
import "../styles/Withdrawals.css";
function Withdrawals() {
  const [data, setData] = useState([]);

  const fetchWithdrawals = async () => {
    try {
      const res = await API.get("/admin/transactions");
      setData(res.data);
    } catch (err) {
      console.log(err);
    }
  };

  const updateStatus = async (id, status) => {
    try {
      await API.put(`/admin/transactions/${id}`, { status });
      fetchWithdrawals(); // refresh
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    fetchWithdrawals();
  }, []);

  return (
    <div>
      <h2>Withdrawal Requests 💸</h2>

      {data.map((t) => (
        <div key={t.transaction_id} className="card">
          
          <p><b>Provider ID:</b> {t.provider_id}</p>
          <p><b>Amount:</b> ₹{t.amount}</p>
          <p><b>Status:</b> {t.status}</p>

          {t.status === "pending" && (
            <>
              <button onClick={() => updateStatus(t.transaction_id, "completed")}>
                Approve
              </button>

              <button onClick={() => updateStatus(t.transaction_id, "rejected")}>
                Reject
              </button>
            </>
          )}

        </div>
      ))}
    </div>
  );
}

export default Withdrawals;
